let lang=read('emr30.lang','bn'), data, view='day', query='', typeFilter='all', yearMode='calendar', bookQuery='';
let progress=read('emr30.progress.v1',{}), selected='', month='', timer={remaining:3000,until:0,running:false};
function read(key,fallback){try{const x=localStorage.getItem(key);return x?JSON.parse(x):fallback}catch{return fallback}}
function save(key,val){try{localStorage.setItem(key,JSON.stringify(val));return true}catch{toast(t('storageError'));return false}}
function t(key){return words[key]?.[lang==='bn'?0:1]??key}
function bi(bn,en){return lang==='bn'?bn:en}
function num(n){return new Intl.NumberFormat(lang==='bn'?'bn-BD':'en-GB').format(n)}
function dateObj(d){return new Date(d+'T12:00:00Z')}
function dateText(d,opts={day:'numeric',month:'long',year:'numeric'}){return new Intl.DateTimeFormat(lang==='bn'?'bn-BD':'en-GB',{...opts,timeZone:'Asia/Dhaka'}).format(dateObj(d))}
function today(){const p=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Dhaka',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());return `${p.find(x=>x.type==='year').value}-${p.find(x=>x.type==='month').value}-${p.find(x=>x.type==='day').value}`}
const validDate=d=>/^\d{4}-\d{2}-\d{2}$/.test(d)&&d>=data.start&&d<=data.end&&Number.isFinite(dateObj(d).getTime())&&dateObj(d).toISOString().slice(0,10)===d;
function getRecord(d=selected){return data.days.find(r=>r.date===d)}
function state(d=selected){return progress[d]||{blocks:{},note:'',score:''}}
const keys=r=>r?.kind==='final'?['attempt','verify','support','english','recall']:['math','physics','support','english','recall'];
function doneCount(r){return r?keys(r).filter(k=>state(r.date).blocks?.[k]===true).length:0}
function completed(){return data.days.filter(r=>doneCount(r)===5)}
function updateProgress(d,patch){progress[d]={...state(d),...patch};save('emr30.progress.v1',progress)}
function pct(){return Math.round(completed().length/262*100)}
function range(rr){return rr.map(([a,b])=>a===b?`${a}`:`${a}–${b}`).join(', ')}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function route(v,d){view=v;if(d&&validDate(d)){selected=d;month=d.slice(0,7);save('emr30.last',d)}const hash=`#${v}${v==='day'?'='+selected:''}`;if(location.hash!==hash)history.pushState(null,'',hash);render();window.scrollTo({top:0,behavior:'instant'})}
function fromHash(){const [v,d]=location.hash.slice(1).split('=');view=['day','year','books','progress','guide'].includes(v)?v:'day';if(d&&validDate(d))selected=d;month=selected.slice(0,7)}
function neighbor(dir){const next=dir>0?data.days.find(r=>r.date>selected):data.days.findLast(r=>r.date<selected);if(next)route('day',next.date)}
function themeUI(){const dark=document.documentElement.dataset.theme==='dark';$('#theme').innerHTML=icon(dark?'sun':'moon');$('#theme').setAttribute('aria-label',bi(dark?'Light theme চালু করো':'Dark theme চালু করো',dark?'Use light theme':'Use dark theme'));$('#theme').setAttribute('aria-pressed',String(dark));$('#language').innerHTML=lang==='bn'?'EN <span aria-hidden="true">⇄</span> বাংলা':'বাংলা <span aria-hidden="true">⇄</span> EN';$('#language').setAttribute('aria-label',lang==='bn'?'Switch to English':'বাংলায় দেখাও')}
function render(){if(!data)return;document.documentElement.lang=lang;document.title=`EMR30 · ${t({day:'daily',year:'navYear',books:'navBooks',progress:'navProgress',guide:'navGuide'}[view])}`;themeUI();$('#navigation').innerHTML=[['day','navDay'],['year','navYear'],['books','navBooks'],['progress','navProgress'],['guide','navGuide']].map(([v,label])=>`<button data-view="${v}" class="${view===v?'active':''}" ${view===v?'aria-current="page"':''}>${t(label)}</button>`).join('');$('#main').innerHTML=({day:dayView,year:yearView,books:booksView,progress:progressView,guide:guideView}[view])();$('#footer').innerHTML=`<div><strong>EMR30 / YEAR 01</strong><br>${t('footer')}</div><div>${t('footerPrivacy')}<br>10 NOV 2026 — 10 NOV 2027</div>`;bind();tick()}
function hero(){return `<section class="hero"><div class="hero-copy"><div class="eyebrow"><span class="dot"></span>${t('heroKicker')}</div><h1>${t('heroTitle')}</h1><p>${t('heroSub')}</p><div class="hero-date">${icon('calendar')}10 NOV 2026 — 10 NOV 2027</div></div><div class="orbital" aria-hidden="true"><i></i><i></i><i></i><b>01</b></div></section><div class="metrics">${[[262,'studyDays','calendar'],[2096,'hours','clock'],[104,'offDays','leaf'],[20,'books','book']].map(([n,k,i])=>`<div class="metric">${icon(i)}<div><strong>${num(n)}</strong><span>${t(k)}</span></div></div>`).join('')}</div>`}
function dayView(){const r=getRecord();return `${hero()}<div class="workspace"><section class="study-column"><div class="section-head"><div><div class="eyebrow">${r?`${t('day')} ${String(r.day).padStart(3,'0')} / 262`:t('off')}</div><h2>${dateText(selected,{day:'numeric',month:'long'})}</h2><p>${dateText(selected,{weekday:'long',year:'numeric'})} · ${t(r?r.kind:'off')}</p></div><div class="date-controls"><button class="icon-button" data-neighbor="-1" aria-label="${t('previous')}" ${selected<=data.start?'disabled':''}>${icon('left')}</button><input class="date-input" id="date-picker" type="date" min="${data.start}" max="${data.end}" value="${selected}" aria-label="${t('date')}"><button class="icon-button" data-neighbor="1" aria-label="${t('next')}" ${selected>=data.end?'disabled':''}>${icon('right')}</button><button class="btn" id="today">${t('today')}</button></div></div>${r?`<div class="day-meta"><span class="tag ${r.kind}">${t(r.kind)}</span><span class="tag">${num(8)}h NET</span><div class="thin-progress" aria-hidden="true"><i style="width:${doneCount(r)*20}%"></i></div><span class="block-count">${num(doneCount(r))}/5 ${t('blocks')}</span></div>${r.kind==='learn'?learning(r):r.kind==='review'?review(r):finalDay(r)}${notes(r)}<div class="day-bottom"><button class="btn" id="print">${icon('print')}${t('print')}</button><button class="btn primary" data-neighbor="1" ${selected>=data.end?'disabled':''}>${t('next')}${icon('arrow')}</button></div>`:`<div class="off-card">${icon('leaf')}<h2>${t('restTitle')}</h2><p>${t('restText')}</p><button class="btn primary" data-neighbor="1">${t('next')}${icon('arrow')}</button></div>`}</section><aside class="sidebar">${calendarPanel(month,true)}<div class="panel"><div class="progress-title"><h3>${t('progress')}</h3><b>${num(pct())}%</b></div><div class="thin-progress"><i style="width:${pct()}%"></i></div><p>${num(completed().length)} / ${num(262)} ${t('completed')}</p><button class="btn text" data-view="progress">${t('navProgress')}${icon('arrow')}</button></div>${focusPanel()}<div class="quiet-note"><b>${t('quietTitle')}</b>${t('quietText')}</div></aside></div>`}
function ref(s){const b=data.books[s.book];return `<div class="reference"><span class="reference-code">${esc(b.code)}</span><div class="reference-copy"><div class="reference-title">${esc(b.title)}</div><div class="reference-author">${esc(b.author)} · ${esc(b.edition)}</div><div class="page-range"><b>PDF ${range(s.ranges)}</b><span>${t('printed')} ${esc(s.printed)}</span></div></div></div>`}
function checkbox(key){return `<label class="check"><input type="checkbox" data-block="${key}" ${state().blocks?.[key]?'checked':''} aria-label="${esc(key)} — ${t('mark')}"><span>${t(state().blocks?.[key]?'done':'mark')}</span></label>`}
function lesson(key,label,time,title,content,extra=''){return `<article class="lesson ${key} ${state().blocks?.[key]?'done':''}"><div class="lesson-top"><span class="lane-label">${icon(key)}${label}<span class="time-tag">· ${time}</span></span>${checkbox(key)}</div><h3>${esc(title)}</h3>${extra}${content}</article>`}
function dailyTask(s,m,lane){if(s.part===m.n||lane==='english')return m.task[lang];let p=Math.min(2,Math.floor((s.part-1)/Math.max(1,m.n-1)*3));if(lane==='math')return bi(['আজকের definitions লেখো; দুটি worked example ঢেকে আবার করো। প্রতিটি algebraic step-এর কারণ লেখো।','আজকের অংশের ৩টি standard exercise ও ১টি reasoning problem করো। Domain ও theorem-এর শর্ত লেখো।','বই বন্ধ করে আজকের একটি result derive/prove করো। তার একটি example ও একটি boundary case বানাও।'][p],['Write today’s definitions and redo two worked examples with solutions covered. Justify every algebraic step.','Solve three standard exercises and one reasoning problem from today’s pages. State domains and theorem conditions.','Derive or prove one result with the book closed. Construct an example and a boundary case.'][p]);if(lane==='physics')return bi(['আজকের model-এর diagram, system boundary ও assumptions লেখো। একটি worked example নিজে আবার করো।','একটি equation নিজে derive করো; ২টি numerical/application problem করো। প্রতিটি উত্তরে units যাচাই করো।','একটি unfamiliar variant solve করো। Zero/infinity/symmetry limit দিয়ে ফল যাচাই করো; কোন assumption ভাঙলে ফল বদলাবে লেখো।'][p],['Draw today’s model; state its system boundary and assumptions. Redo one worked example independently.','Derive one equation and solve two numerical/application problems. Check units in every answer.','Solve an unfamiliar variant. Check zero, infinite and symmetry limits; explain which broken assumption would change the result.'][p]);if(s.book==='PYTHON')return bi('আজকের page range-এর code/example নিজে লিখে চালাও; একটি input বা parameter বদলে result predict করে যাচাই করো। Error ও fix notebook-এ রাখো।','Write and run the code/example from today’s pages. Change an input or parameter, predict the result and check it. Log the error and fix.');if(s.book==='STATS')return bi('আজকের সংজ্ঞা নিজের ভাষায় লেখো; একটি worked example হাতে আবার করো এবং নতুন dataset/parameter দিয়ে পরীক্ষা করো।','Restate today’s definitions, redo one worked example by hand and test it with a new dataset or parameter.');return bi('আজকের পাঠ থেকে একটি proof/example বই বন্ধ করে লেখো; নিজের একটি example বা counterexample দাও।','Write one proof/example with the book closed; add an example or counterexample of your own.')}
function moduleCard(r,lane){const s=r[lane],m=data.modules[lane][s.unit];return lesson(lane,lane.toUpperCase(),t({math:'readMath',physics:'readPhysics',support:'h1',english:'hHalf'}[lane]),m.title,`${ref(s)}${s.hint?`<p class="hint">${t('section')}: ${esc(s.hint)}</p>`:''}<p class="instruction"><strong>${t('why')}:</strong> ${esc(m.why[lang])}</p><p class="instruction"><strong>${t('task')}:</strong> ${esc(dailyTask(s,m,lane))}</p>${lane!=='english'?`<details class="unit-goal"><summary>${t('goal')}</summary><p>${esc(m.task[lang])}</p></details>`:''}`,`<p class="course">${esc(m.code)} · ${t('part')} ${num(s.part)} / ${num(m.n)}</p>`)}
function recall(r){const prior=[1,5,20].map(x=>r.day-x).filter(x=>x>0);return lesson('recall','RECALL',t('hHalf'),t('recallTitle'),`<p class="instruction">${t('recallBody')}</p><div class="recall-links">${prior.map(n=>`<button data-date="${data.days[n-1].date}">D${String(n).padStart(3,'0')} · ${dateText(data.days[n-1].date,{day:'numeric',month:'short'})}</button>`).join('')||`<p class="small muted">${t('baseline')}</p>`}</div>`)}
function learning(r){return moduleCard(r,'math')+moduleCard(r,'physics')+moduleCard(r,'support')+`<div class="compact-lessons">${moduleCard(r,'english')}${recall(r)}</div>`}
function collapsePages(pages){const out=[];[...new Set(pages)].sort((a,b)=>a-b).forEach(p=>{if(out.length&&out.at(-1)[1]===p-1)out.at(-1)[1]=p;else out.push([p,p])});return out}
function reviewRefs(r,lane){const byBook={};data.days.slice(Math.max(0,r.day-10),r.day-1).forEach(x=>{if(x[lane]){const s=x[lane];byBook[s.book]??=[];s.ranges.forEach(([a,b])=>{for(let p=a;p<=b;p++)byBook[s.book].push(p)})}});return `<p class="course">${t('reviewPages')}</p>`+Object.entries(byBook).map(([k,p])=>`<p class="small muted"><strong>${esc(data.books[k].code)}</strong> · ${esc(data.books[k].title)} · <b>PDF ${range(collapsePages(p))}</b></p>`).join('')}
function review(r){const lab=data.labs[r.day/10-1];return lesson('math','MATHEMATICS',t('h3'),bi('Test, correction ও derivation','Test, correct and derive'),`${reviewRefs(r,'math')}<p class="instruction">${t('reviewMath')}</p>`)+lesson('physics','PHYSICS LAB',t('h3'),lab.title,`${ref(lab)}<p class="instruction">${esc(lab.task[lang])}</p><p class="unit-goal">${t('reviewLab')}</p>`)+lesson('support','SUPPORT',t('h1'),bi('দুর্বল অংশ মেরামত','Repair the weak links'),`${reviewRefs(r,'support')}<p class="instruction">${t('reviewSupport')}</p>`)+`<div class="compact-lessons">${lesson('english','ENGLISH',t('hHalf'),bi('আজকের ফল লেখো','Write up your findings'),`${reviewRefs(r,'english')}<p class="instruction">${t('reviewEnglish')}</p>`)}${recall(r)}</div>`}
function finalDay(r){const f=data.finals[r.day-251];return `<h2 style="margin:24px 0">${esc(f.title)}</h2>`+lesson('attempt','ASSESSMENT',t('h3'),t('firstThree'),`${f.refs.map(ref).join('')}<p class="instruction">${esc(f.task[lang])}</p><p class="unit-goal">${t('finalAttempt')}</p>`)+lesson('verify','VERIFY & DOCUMENT',t('h3'),t('secondThree'),`<p class="instruction">${esc(f.followup[lang])}</p><p class="unit-goal">${t('finalFollow')}</p>`)+lesson('support','SUPPORT',t('h1'),bi('Prerequisite যাচাই','Check your prerequisites'),`<p class="instruction">${t('finalSupport')}</p>`)+`<div class="compact-lessons">${lesson('english','ENGLISH',t('hHalf'),bi('ফলাফল লিখে রাখো','Document the result'),`<p class="instruction">${t('finalEnglish')}</p>`)}${recall(r)}</div>`}
function notes(){return `<section class="notes"><label for="day-notes">${t('notes')}</label><textarea id="day-notes" maxlength="12000" placeholder="${t('notesHint')}">${esc(state().note||'')}</textarea><div class="notes-bottom"><span>${t('autosave')}</span><label for="day-score" style="font-size:11px;margin:0">${t('score')} <input id="day-score" type="number" min="0" max="100" step="1" value="${esc(state().score??'')}"> / 100</label><button class="btn text" id="share">${icon('link')}${t('share')}</button></div></section>`}
function calendarPanel(ym,arrows=false){const [y,m]=ym.split('-').map(Number),first=new Date(Date.UTC(y,m-1,1)).getUTCDay(),last=new Date(Date.UTC(y,m,0)).getUTCDate();let tiles='';for(let i=0;i<first;i++)tiles+='<span class="empty"></span>';for(let d=1;d<=last;d++){const iso=`${ym}-${String(d).padStart(2,'0')}`;if(iso<data.start||iso>data.end){tiles+='<span class="empty"></span>';continue}const r=getRecord(iso);tiles+=`<button data-date="${iso}" class="${r?r.kind:'off'} ${iso===selected?'selected':''} ${r&&doneCount(r)===5?'complete':''}" aria-label="${dateText(iso)} — ${r?`${t('day')} ${r.day}, ${t(r.kind)}`:t('off')}" ${iso===selected?'aria-current="date"':''}>${num(d)}</button>`}return `<section class="panel calendar-panel"><div class="calendar-title">${arrows?`<button class="icon-button" data-month="-1" aria-label="${t('previousMonth')}" ${ym<=data.start.slice(0,7)?'disabled':''}>${icon('left')}</button>`:''}<strong>${dateText(ym+'-01',{month:'long',year:'numeric'})}</strong>${arrows?`<button class="icon-button" data-month="1" aria-label="${t('nextMonth')}" ${ym>=data.end.slice(0,7)?'disabled':''}>${icon('right')}</button>`:''}</div><div class="calendar-grid">${bi(['রবি','সোম','মঙ্গল','বুধ','বৃহঃ','শুক্র','শনি'],['Su','Mo','Tu','We','Th','Fr','Sa']).map(s=>`<span class="weekday">${s}</span>`).join('')}${tiles}</div><div class="calendar-legend"><span>${t('done')}</span><span>${t('review')}</span><span>${t('off')}</span></div></section>`}
function focusPanel(){return `<section class="panel focus-panel"><div class="focus-heading"><h3>${t('focus')}</h3>${icon('clock')}</div><div class="focus-clock" id="focus-clock" role="timer" aria-live="off">50:00</div><div class="focus-actions"><button class="btn primary" id="focus-toggle">${icon(timer.running?'pause':'play')}${t(timer.running?'pause':timer.remaining===3000?'start':'resume')}</button><button class="icon-button" id="focus-reset" aria-label="${t('reset')}">${icon('reset')}</button></div><p>${t('focusNote')}</p></section>`}
function tick(){if(timer.running){timer.remaining=Math.max(0,Math.ceil((timer.until-Date.now())/1000));if(!timer.remaining){timer.running=false;toast(t('focusDone'));if($('#focus-toggle'))$('#focus-toggle').innerHTML=icon('play')+t('start')}}if($('#focus-clock'))$('#focus-clock').textContent=`${String(Math.floor(timer.remaining/60)).padStart(2,'0')}:${String(timer.remaining%60).padStart(2,'0')}`}
setInterval(tick,500);
function searchable(r){let text=`${r.date} ${r.day} ${r.kind} `;if(r.kind==='learn')for(const lane of ['math','physics','support','english']){const m=data.modules[lane][r[lane].unit],b=data.books[m.book];text+=`${lane} ${m.title} ${m.code} ${b.title} ${b.author} ${b.code} ${m.why.bn} ${m.why.en} ${m.task.bn} ${m.task.en} `}else if(r.kind==='review'){const l=data.labs[r.day/10-1];text+=`${l.title} ${l.task.bn} ${l.task.en} ${data.books[l.book].title}`}else{const f=data.finals[r.day-251];text+=`${f.title} ${f.task.bn} ${f.task.en} ${f.refs.map(x=>data.books[x.book].title).join(' ')}`}for(const match of text.matchAll(/(MATH|PHY|STAT|ENG)-(\d{3}(?:\/\d{3})*)/g)){text+=' '+match[2].split('/').map(n=>match[1]+'-'+n).join(' ')}return text.toLowerCase()}
function heading(kicker,title,sub){return `<header class="page-heading"><div class="eyebrow">${kicker}</div><h1>${t(title)}</h1><p>${t(sub)}</p></header>`}
function yearView(){return heading('THE READING PATH','yearTitle','yearSub')+`<div class="filters"><div class="search-wrap">${icon('search')}<input id="search" type="search" placeholder="${t('search')}" aria-label="${t('search')}" value="${esc(query)}"></div><select id="type-filter" aria-label="${t('all')}">${['all','learn','review','final'].map(k=>`<option value="${k}" ${typeFilter===k?'selected':''}>${t(k)}</option>`).join('')}</select><select id="year-mode" aria-label="${t('calendar')} / ${t('list')}"><option value="calendar" ${yearMode==='calendar'?'selected':''}>${t('calendar')}</option><option value="list" ${yearMode==='list'?'selected':''}>${t('list')}</option></select></div><div id="year-results">${yearResults()}</div>`}
function yearResults(){if(!query&&typeFilter==='all'&&yearMode==='calendar'){let months=[];let d=new Date('2026-11-01T00:00:00Z');while(d.toISOString().slice(0,7)<='2027-11'){months.push(d.toISOString().slice(0,7));d.setUTCMonth(d.getUTCMonth()+1)}return `<div class="calendar-year">${months.map(m=>calendarPanel(m)).join('')}</div>`}const q=query.toLowerCase().trim(),rows=data.days.filter(r=>(typeFilter==='all'||r.kind===typeFilter)&&(!q||searchable(r).includes(q)));return `<p class="small muted" style="margin-bottom:16px">${num(rows.length)} ${t('result')}</p><div class="results">${rows.map(r=>{const title=r.kind==='learn'?data.modules.math[r.math.unit].title+' · '+data.modules.physics[r.physics.unit].title:r.kind==='review'?data.labs[r.day/10-1].title:data.finals[r.day-251].title;return `<button class="result-row" data-date="${r.date}"><span class="result-number">DAY ${String(r.day).padStart(3,'0')}${doneCount(r)===5?' ✓':''}</span><span class="result-body"><h3>${esc(title)}</h3><p>${dateText(r.date)} · ${t(r.kind)} · 8h</p></span>${icon('arrow')}</button>`}).join('')||`<div class="empty-message">${t('noResults')}</div>`}</div>`}
function booksView(){return heading('THE PERSONAL LIBRARY','booksTitle','booksSub')+`<div class="notice">${t('bookNotice')}</div><div class="filters"><div class="search-wrap">${icon('search')}<input id="book-search" type="search" placeholder="${t('bookSearch')}" aria-label="${t('bookSearch')}" value="${esc(bookQuery)}"></div></div><div class="book-grid" id="book-results">${bookResults()}</div>`}
function bookResults(){const rows=Object.values(data.books).filter(b=>`${b.title} ${b.author} ${b.code}`.toLowerCase().includes(bookQuery.toLowerCase().trim()));return rows.map(b=>`<article class="book-card"><span class="book-code">${esc(b.code)}</span><h3>${esc(b.title)}</h3><p>${esc(b.author)}</p><p>${esc(b.edition)} · ${num(b.pages)} ${t('pageCount')}</p><div class="filename"><strong>${t('filename')}</strong><br>${esc(b.filename)}</div><div class="spacer"></div><button class="btn text" data-book="${esc(b.title)}">${t('seeDays')}${icon('arrow')}</button></article>`).join('')||`<p class="empty-message">${t('noResults')}</p>`}
function progressView(){const complete=completed();let count=0,hours=0;for(const r of data.days)keys(r).forEach((k,i)=>{if(state(r.date).blocks?.[k]===true){count++;hours+=[3,3,1,.5,.5][i]}});const next=data.days.find(r=>doneCount(r)<5);return heading('SHOW UP. KEEP THE EVIDENCE.','progressTitle','progressSub')+`<div class="progress-grid"><section class="panel"><h2>${t('completed')}</h2><div class="stats-large">${num(complete.length)} <span class="muted" style="font-size:23px">/ ${num(262)}</span></div><div class="thin-progress"><i style="width:${pct()}%"></i></div><p>${num(count)} ${t('savedBlocks')} · ${num(hours)} ${t('plannedHours')}</p></section><section class="panel"><h2>${t('continue')}</h2><p>${next?`${t('day')} ${num(next.day)} · ${dateText(next.date)}`:t('allComplete')}</p>${next?`<button class="btn primary" style="margin-top:23px" data-date="${next.date}">${t('continueBtn')}${icon('arrow')}</button>`:''}</section><section class="panel"><h2>${t('backupTitle')}</h2><p>${t('backupText')}</p><div class="backup-actions"><button class="btn primary" id="export">${icon('download')}${t('export')}</button><button class="btn" id="import">${icon('upload')}${t('import')}</button></div></section><section class="panel"><h2>${t('recent')}</h2><div class="completion-list">${complete.length?complete.map(r=>`<button class="btn" data-date="${r.date}">D${String(r.day).padStart(3,'0')} ${icon('check')}</button>`).join(''):`<p>${t('noComplete')}</p>`}</div></section></div>`}

function coverageTable(){const rows=[];for(const [prefix,start,end] of [['PHY',101,107],['MATH',101,111],['STAT',101,103],['ENG',101,103]])for(let n=start;n<=end;n++){const code=prefix+'-'+n;const days=data.days.filter(r=>r.kind==='learn'&&['math','physics','support','english'].some(lane=>{const raw=data.modules[lane][r[lane].unit].code;let active='';return raw.split('/').some(part=>{if(part.includes('-')){active=part.split('-')[0];return part===code}return active+'-'+part===code})}));const a=days[0],b=days.at(-1);rows.push(`<div class="schedule-row" style="flex-wrap:wrap;align-items:center"><strong>${code}</strong><span><button class="btn" data-date="${a.date}">D${String(a.day).padStart(3,'0')}</button> → <button class="btn" data-date="${b.date}">D${String(b.day).padStart(3,'0')}</button> <small class="muted">(${num(days.length)} ${t('studyDays')})</small></span></div>`)}return `<details style="margin-top:16px"><summary>${bi('২৪-course coverage table দেখো','View the 24-course coverage table')}</summary><p>${bi('প্রথম ও শেষ উপস্থিতি দেখানো হলো; মাঝখানে বিরতি থাকতে পারে।','First and last appearances are shown; a course may have gaps between them.')}</p>${rows.join('')}</details>`}
function guideView(){const section=(title,content,wide=false)=>`<section class="guide-card ${wide?'wide':''}"><h2>${title}</h2>${content}</section>`,p=s=>`<p>${s}</p>`,ul=rows=>`<ul>${rows.map(x=>`<li>${x}</li>`).join('')}</ul>`;return heading('THE STUDY METHOD','guideTitle','guideSub')+`<div class="guide-grid">`+
section(bi('পরিসর ও নিয়ম','Scope & ground rules'),ul(bi([
'10 Nov 2026–10 Nov 2027, দুই দিনসহ। Sunday–Thursday প্রতিদিন ৮ ঘণ্টা net study; খাওয়া ও বিরতি আলাদা। Friday ও Saturday ০ ঘণ্টা।',
'Physics, Mathematics, Statistics ও Scientific English: ২৪টি course। Standalone CSE/CS, ICT, Chemistry ও History বাদ। PHY-102-এর physics computing অন্তর্ভুক্ত।',
'225টি নতুন-পাঠের দিন, 25টি review/lab দিন, শেষে 12টি assessment/capstone দিন। এটি syllabus-কেন্দ্রিক নির্বাচিত পাঠপথ; প্রতিটি reference book-এর সব পৃষ্ঠা বাধ্যতামূলক নয়।',
'STAT-103 বিস্তারিত syllabus-এ Year 1–2, complete curriculum-এ Year 1; এখানে curriculum অনুযায়ী প্রথম বর্ষে রাখা হয়েছে।'
],[
'10 Nov 2026–10 Nov 2027, inclusive. Study 8 net hours Sunday–Thursday; meals and breaks are separate. Friday and Saturday: zero hours.',
'24 courses in Physics, Mathematics, Statistics and Scientific English. Standalone CSE/CS, ICT, Chemistry and History are excluded. Physics computing in PHY-102 is included.',
'225 learning days, 25 review/lab days and 12 final assessment/capstone days. This is a syllabus-focused reading path; it does not require every page of every reference book.',
'STAT-103 spans Years 1–2 in the detailed syllabus but appears in Year 1 of the complete curriculum. This plan follows the latter placement.'
])))+
section(bi('৮ ঘণ্টার দৈনিক ব্যবস্থা','Your 8-hour routine'),[['Mathematics',t('readMath')],['Physics',t('readPhysics')],['Support',t('h1')],['Scientific English',t('hHalf')],['Recall & error log',t('hHalf')]].map(([k,v])=>`<div class="schedule-row"><strong>${k}</strong><span>${v}</span></div>`).join('')+p(bi('Math পাঠে ৪০ মিনিট reading, ৪০ মিনিট worked example, ৪০ মিনিট definition/derivation। Physics পাঠে ৭০ মিনিট reading, ৩০ মিনিট derivation, ২০ মিনিট diagram/assumptions। Support: ২৫ মিনিট reading + ৩৫ মিনিট hands-on। English: ১০ মিনিট reading + ২০ মিনিট লেখা/বলা।','For Math reading: 40 min reading, 40 min worked examples and 40 min definitions/derivations. For Physics reading: 70 min reading, 30 min derivation and 20 min diagrams/assumptions. Support: 25 min reading + 35 min hands-on. English: 10 min reading + 20 min writing/speaking.')))+
section(bi('সঠিক পৃষ্ঠা ও অনুশীলন','Exact pages & practice'),ul(bi([
'Physical PDF page হলো cover থেকে গণনা, দুই endpoint-সহ। Printed/label আলাদা। অন্য scan বা edition-এ offset বদলে যায়; Bookshelf-এর filename ও page count মেলাও। Abbott-এর labels একটিমাত্র offset মেনে চলে না।',
'Range-এর theory, definitions ও worked examples পড়ো। Proof আগের পৃষ্ঠায় শুরু হলে context-এর জন্য আগের ১–২ পৃষ্ঠা দেখো। Exercise bank-এর সব প্রশ্ন শেষ করতে হবে না।',
'Math practice: ৩টি standard + ১টি transfer/proof problem। Physics: ২টি standard + ১টি unfamiliar application; units ও limits যাচাই। Exercise না থাকলে worked example-এর values বদলে variant বানাও।',
'নিজে বেছে নেওয়া problem number, section ও book code খাতায় লেখো। যাচাইহীন exercise number বানিয়ে দেওয়া হয়নি। Unit-এর goal কয়েক দিনে তৈরি হবে; শেষ অংশে সম্পূর্ণ করবে।'
],[
'Physical PDF pages are counted from the cover, including both endpoints. Printed/label numbers are separate. Match the Bookshelf filename and page count; another scan or edition changes offsets. Abbott’s labels do not follow a single offset.',
'Read theory, definitions and worked examples in the range. Look back 1–2 pages if a proof begins earlier. You do not need to finish the entire exercise bank.',
'Math practice: three standard problems plus one transfer/proof. Physics: two standard problems plus one unfamiliar application; check units and limits. Where there are no exercises, change values in a worked example to create variants.',
'Record your selected problem numbers, sections and book codes. Unverified exercise numbers have not been invented. Build each unit goal over its parts and finish it on the last part.'
])))+
section(bi('Mastery ও আটকে যাওয়ার নিয়ম','Mastery & getting unstuck'),ul(bi([
'২৫ মিনিট নিজে চেষ্টা, তারপর প্রয়োজনীয় hint বা definition। Solution দেখলে খাতা বন্ধ করে আবার করো। অসম্পূর্ণ কাজ consolidation day-এর repair block-এ যাবে।',
'নিজের rubric: model/definition ও assumptions 20, reasoning/proof 30, calculation/units/notation 20, independent check 15, explanation ও correction 15। 80+: নতুন problem-এ প্রয়োগ পারলে এগোও। 70–79: repair। 70-এর নিচে prerequisite আবার পড়ো। এটি university grading policy নয়।',
'পরপর দুটি check-এ 70%-এর নিচে হলে নতুন prerequisite-dependent পাঠ ধীর করো। Deadline-এর জন্য বোঝাপড়া এড়িয়ে যাবে না।',
'Spaced recall: আগের 1, 5 ও 20তম study day; Friday/Saturday গণনায় নেই। Study desk-এ সেই দিনের direct link আছে।'
],[
'Try independently for 25 minutes, then consult a necessary hint or definition. If you read a solution, close it and redo the problem. Carry unfinished work into a consolidation repair block.',
'Self-study rubric: model/definition and assumptions 20, reasoning/proof 30, calculation/units/notation 20, independent check 15, explanation and correction 15. At 80+, proceed if you can transfer the idea. At 70–79, repair. Below 70, revisit the prerequisite. This is not university grading policy.',
'After two checks below 70%, slow down dependent new material. Do not trade understanding for the calendar deadline.',
'Spaced recall revisits the previous 1st, 5th and 20th study days. Friday/Saturday are excluded. Direct links appear on the study desk.'
])))+
section('Foundation bridge',`<details><summary>ZFC & set construction</summary>${p(bi('Unrestricted comprehension থেকে Russell paradox আসে। ZFC-তে Extensionality, Empty Set, Pairing, Union, Power Set, Infinity, Separation schema, Replacement schema, Foundation ও Choice দিয়ে set construction নিয়ন্ত্রিত; কিছু formulation-এ Empty Set অন্য axioms থেকে আসে। একই elements হলে একই set (Extensionality); আগে থাকা set-এর property-ভিত্তিক subset (Separation); সব subsets-এর set (Power Set); natural-number construction-এর জন্য infinite set (Infinity); nonempty sets-এর family থেকে selection function-এর অস্তিত্ব (Choice)।','Unrestricted comprehension leads to Russell’s paradox. ZFC controls set construction through Extensionality, Empty Set, Pairing, Union, Power Set, Infinity, Separation, Replacement, Foundation and Choice; some formulations derive Empty Set. Extensionality identifies sets with identical elements; Separation selects a subset of an existing set; Power Set collects all subsets; Infinity supports natural-number construction; Choice asserts a selection function for a family of nonempty sets.'))}${p(bi('কাজ: “সব sets-এর set” কেন বিপজ্জনক লিখো। Separation ও unrestricted comprehension তুলনা করো। এই বছরে axioms-এর অর্থ ও ব্যবহার শেখাই লক্ষ্য; independence proofs পরের পাঠ।','Task: explain the danger of a “set of all sets.” Compare Separation with unrestricted comprehension. This year introduces meanings and uses; metamathematical independence proofs come later.'))}</details><details><summary>Group → Ring → Field</summary>${p(bi('Group: associative operation, identity, প্রত্যেক element-এর inverse; commutative হলে abelian। (Z,+) group, (N,+) সাধারণভাবে নয়। Ring: addition-এর abelian group, associative multiplication, distributivity; এখানে multiplicative identity ধরা হচ্ছে। Z ring। Field: commutative ring, 0≠1, nonzero elements-এর multiplicative inverse। Q, R ও prime p-এর Z/pZ field।','A group has an associative operation, identity and inverse for every element; it is abelian if commutative. (Z,+) is a group; (N,+) generally is not. A ring has an additive abelian group, associative multiplication and distributivity; this note assumes a multiplicative identity. Z is a ring. A field is a commutative ring with 0≠1 and multiplicative inverses for nonzero elements. Q, R and Z/pZ for prime p are fields.'))}${p(bi('Z/6Z-এ nonzero 2×3=0 দেখাও। Z/5Z-এর nonzero inverses লেখো। প্রত্যেক structure-এর ৩টি example/non-example দাও; কোন axiom ব্যর্থ তা বলো। একটি example universal proof নয়: statement, assumptions, definitions, argument ও conclusion লেখো।','Show nonzero 2×3=0 in Z/6Z. List nonzero inverses in Z/5Z. Give three examples/non-examples of each structure and identify failed axioms. An example is not a universal proof: write the statement, assumptions, definitions, argument and conclusion.'))}</details>`)+
section(bi('Lab ও computation bridge','Lab & computation bridge'),`<details><summary>${bi('Measurement ও notebook','Measurement & notebooks')}</summary>${p(bi('খাতা, ruler, stopwatch, সুতা, হালকা pendulum bob, calculator ও computer দিয়ে শুরু করো। Household measurement সম্ভব না হলে simulation করে স্পষ্ট label দাও। PHY-102 শুরুতে Jupyter notebook-এ Markdown cell-এ question/units, code cell-এ calculation, শেষে interpretation রাখো। Fresh kernel → Run all → same result দিয়ে যাচাই করো। Newman-এর পুরোনো API বর্তমান NumPy/SciPy docs-এ মিলিয়ে নেবে।','Start with a notebook, ruler, stopwatch, string, light pendulum bob, calculator and computer. If household measurement is unavailable, label simulations explicitly. In PHY-102, use Markdown cells for questions/units, code cells for calculations and a final interpretation. Verify fresh kernel → Run all → same result. Check older Newman APIs against current NumPy/SciPy documentation.'))}</details><details><summary>Oscilloscope & data logger</summary>${p(bi('Vertical V/div ও horizontal s/div পড়বে। 3 divisions × 0.5 V/div = 1.5 V amplitude। Period 4 divisions × 2 ms/div = 8 ms; f=125 Hz। Peak ও peak-to-peak আলাদা; zero offset, probe attenuation ও trigger নথিবদ্ধ করো। Data logger-এ channel, unit, calibration, timestamp ও sampling interval লেখো। Band-limited signal-এর Nyquist limit fₛ/2; বাস্তবে filter ও margin দরকার। Synthetic sine দিয়ে aliasing দেখো।','Read vertical V/div and horizontal s/div. 3 divisions × 0.5 V/div = 1.5 V amplitude. A period of 4 divisions × 2 ms/div = 8 ms gives f=125 Hz. Distinguish peak from peak-to-peak; record zero offset, probe attenuation and trigger. For data loggers record channel, unit, calibration, timestamp and sampling interval. A band-limited signal has a Nyquist limit fₛ/2; practical use requires filtering and margin. Demonstrate aliasing with a synthetic sine.'))}</details>${p(bi('Circuit simulation-এ করো; পরিচিত বাস্তব setup হলে ≤5 V supply। Mains ব্যবহার নয়। Cooling-এ হালকা গরম পানি যথেষ্ট। পূর্ণ university lab skill-এর জন্য supervised real-instrument practice প্রয়োজন।','Use circuit simulations; for a familiar physical setup use a supply of at most 5 V, never mains. Mildly warm water suffices for cooling. Full university lab competency requires supervised practice on real instruments.'))}`)+
section(bi('Scientific writing bridge','Scientific writing bridge'),ul(bi([
'প্রতিটি reading-এ প্রশ্ন: claim কী? model/assumptions/data কী? কী observation claim-কে ভুল প্রমাণ করত? uncertainty/alternative কী? ফল কোন পরিস্থিতিতে প্রযোজ্য?',
'CRAAP: Currency, Relevance, Authority, Accuracy, Purpose। SIFT: Stop; Investigate the source; Find better coverage; Trace to original context।',
'একটি report-এ citation style ধারাবাহিক রাখো। Practice-এ একই source APA author-year, IEEE numbered ও Chicago note-এ সাজাও। Book: author/title/edition/publisher/year/page। Web: title/URL/access date। Paraphrase-এও citation প্রয়োজন।',
'Draft ৪৮ ঘণ্টা পরে আবার পড়ো: claim-supported, method reproducible, units consistent, figure understandable, uncertainty honest? External feedback না হলে সেটিকে self-review বলো।',
'Essay: “একটি physical model-কে বিশ্বাস করার জন্য কী evidence দরকার?” ১,৫০০ শব্দ, ৩টি draft, mechanics/thermal/E&M উদাহরণ, অন্তত ৪টি verified source, শক্ত counterargument ও conclusion।'
],[
'For each reading ask: what is the claim? Which model, assumptions and data? What observation could falsify it? Which uncertainties and alternatives? Under what conditions does the result apply?',
'CRAAP: Currency, Relevance, Authority, Accuracy, Purpose. SIFT: Stop; Investigate the source; Find better coverage; Trace to original context.',
'Keep one consistent citation style per report. Practise APA author-year, IEEE numbered and Chicago note styles on the same source. Record book author/title/edition/publisher/year/page and web title/URL/access date. Paraphrases also need citations.',
'Reread a draft after 48 hours: supported claims, reproducible method, consistent units, clear figures, honest uncertainty? Without outside feedback, call it self-review.',
'Essay: “What evidence justifies trusting a physical model?” Write 1,500 words in three drafts, with mechanics/thermal/E&M examples, at least four verified sources, a strong counterargument and conclusion.'
])))+
section(bi('বছর শেষে evidence','Your year-end evidence'),ul(bi([
'কমপক্ষে ৫০টি পরিষ্কার proof/derivation ও ১০টি mixed problem set।',
'দুটি investigation report: pendulum এবং cooling/RC; measured/simulated data স্পষ্ট label।',
'১,৫০০ শব্দের cited analytical essay, ৩টি draft ও revision trail।',
'Reproducible notebook: raw data → analysis → figure → uncertainty → conclusion।',
'১০ মিনিটের oral presentation, প্রশ্নোত্তর ও Year 2 prerequisite repair list। Calendar শেষ হওয়া নিজে mastery-এর প্রমাণ নয়।'
],[
'At least 50 clear proofs/derivations and 10 mixed problem sets.',
'Two investigation reports: pendulum and cooling/RC, with clearly labelled measured or simulated data.',
'A cited 1,500-word analytical essay with three drafts and a revision trail.',
'A reproducible notebook: raw data → analysis → figure → uncertainty → conclusion.',
'A ten-minute oral presentation, questions and answers, and a Year 2 prerequisite repair list. Finishing the calendar does not itself demonstrate mastery.'
])))+
section(bi('Course coverage','Course coverage'),`<p>PHY-101–107 · MATH-101–111 · STAT-101–103 · ENG-101–103</p>${p(bi('Your year-এর search-এ course code দিয়ে দিনগুলো খোঁজো। একই course পরে আবার ফিরতে পারে। STAT-102 software work Python-এ; আলাদা R course প্রয়োজন নেই। PHY-101-এর ethics ও research habits report/writing-এও অনুশীলন হবে।','Search course codes in Your year to find their days. Courses can recur later. STAT-102 software work uses Python, with no separate R course required. PHY-101 ethics and research habits also appear in reports and writing.'))}${coverageTable()}`)+
section(bi('Official learning tools','Official learning tools'),ul([['Try Jupyter','https://jupyter.org/try'],['NumPy documentation','https://numpy.org/doc/'],['SciPy documentation','https://docs.scipy.org/doc/scipy/'],['PhET simulations','https://phet.colorado.edu/'],['Book of Proof · Richard Hammack','https://richardhammack.github.io/BookOfProof/']].map(([n,u])=>`<a href="${u}" target="_blank" rel="noopener noreferrer">${n} ↗</a>`))+p(bi('প্রথমবার online-এ খোলার পর মূল site offline-এও পাওয়া যাবে। External tools-এর জন্য internet লাগবে। Notes ও progress হারানোর আগে Export করে backup রাখো।','After the first online load, the core site is available offline. External tools need internet. Export backups to protect your notes and progress.')))+`</div>`}

function bindDateButtons(root=document){$$('[data-date]',root).forEach(b=>b.addEventListener('click',()=>route('day',b.dataset.date)))}
function bindBookButtons(){$$('[data-book]').forEach(b=>b.addEventListener('click',()=>{query=b.dataset.book;typeFilter='all';yearMode='list';route('year')}))}
function bind(){bindDateButtons();bindBookButtons();$$('[data-view]').forEach(b=>b.addEventListener('click',()=>route(b.dataset.view)));$$('[data-neighbor]').forEach(b=>b.addEventListener('click',()=>neighbor(Number(b.dataset.neighbor))));$$('[data-block]').forEach(b=>b.addEventListener('change',()=>{const blocks={...state().blocks,[b.dataset.block]:b.checked};updateProgress(selected,{blocks});const y=scrollY;render();window.scrollTo({top:y,behavior:'instant'});$(`[data-block="${b.dataset.block}"]`)?.focus({preventScroll:true})}));$('#date-picker')?.addEventListener('input',e=>{if(validDate(e.target.value))route('day',e.target.value)});$('#today')?.addEventListener('click',()=>route('day',today()<data.start?data.start:today()>data.end?data.end:today()));$$('[data-month]').forEach(b=>b.addEventListener('click',()=>{const d=dateObj(month+'-01');d.setUTCMonth(d.getUTCMonth()+Number(b.dataset.month));month=d.toISOString().slice(0,7);const y=scrollY;render();window.scrollTo({top:y,behavior:'instant'})}));$('#day-notes')?.addEventListener('input',e=>updateProgress(selected,{note:e.target.value}));$('#day-score')?.addEventListener('input',e=>{const s=e.target.value===''?'':Math.min(100,Math.max(0,Math.round(Number(e.target.value))));e.target.value=s;updateProgress(selected,{score:s})});$('#print')?.addEventListener('click',()=>{const details=$$('.unit-goal');details.forEach(d=>d.open=true);window.print()});$('#share')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(location.origin+location.pathname+'#day='+selected);toast(t('copied'))}catch{toast(t('copyFail'))}});$('#focus-toggle')?.addEventListener('click',()=>{if(timer.running){tick();timer.running=false}else{if(timer.remaining===0)timer.remaining=3000;timer.until=Date.now()+timer.remaining*1000;timer.running=true}const y=scrollY;render();window.scrollTo({top:y,behavior:'instant'})});$('#focus-reset')?.addEventListener('click',()=>{timer={remaining:3000,until:0,running:false};const y=scrollY;render();window.scrollTo({top:y,behavior:'instant'})});const refreshResults=()=>{$('#year-results').innerHTML=yearResults();bindDateButtons($('#year-results'))};$('#search')?.addEventListener('input',e=>{query=e.target.value;refreshResults()});$('#type-filter')?.addEventListener('change',e=>{typeFilter=e.target.value;refreshResults()});$('#year-mode')?.addEventListener('change',e=>{yearMode=e.target.value;refreshResults()});$('#book-search')?.addEventListener('input',e=>{bookQuery=e.target.value;$('#book-results').innerHTML=bookResults();bindBookButtons()});$('#export')?.addEventListener('click',exportBackup);$('#import')?.addEventListener('click',()=>$('#import-file').click())}
function exportBackup(){const backup={format:'emr30-progress',version:1,exported:new Date().toISOString(),progress};const blob=new Blob([JSON.stringify(backup,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`emr30-progress-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(t('exported'))}
$('#import-file').addEventListener('change',async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>10000000)throw Error();const b=JSON.parse(await file.text());if(b.format!=='emr30-progress'||b.version!==1||!b.progress||typeof b.progress!=='object'||Array.isArray(b.progress))throw Error();const clean={};for(const [d,s]of Object.entries(b.progress)){const r=getRecord(d);if(!r||!s||typeof s!=='object'||!s.blocks||typeof s.blocks!=='object'||typeof s.note!=='string'||s.note.length>12000)throw Error();const blocks={};for(const k of keys(r)){if(s.blocks[k]!==undefined&&typeof s.blocks[k]!=='boolean')throw Error();blocks[k]=s.blocks[k]===true}const score=s.score??'';if(score!==''&&(!Number.isInteger(score)||score<0||score>100))throw Error();clean[d]={blocks,note:s.note,score}}progress={...progress,...clean};if(save('emr30.progress.v1',progress)){render();toast(t('imported'))}}catch{toast(t('invalidBackup'))}finally{e.target.value=''}});
$('#language').addEventListener('click',()=>{lang=lang==='bn'?'en':'bn';save('emr30.lang',lang);const y=scrollY;render();window.scrollTo({top:y,behavior:'instant'})});
$('#theme').addEventListener('click',()=>{const next=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=next;try{localStorage.setItem('emr30.theme',next)}catch{}themeUI()});
window.addEventListener('popstate',()=>{fromHash();render()});
window.addEventListener('storage',e=>{if(e.key==='emr30.progress.v1'){progress=read('emr30.progress.v1',{});render()}});
fetch('./data.json').then(r=>{if(!r.ok)throw Error(r.status);return r.json()}).then(d=>{data=d;if(!['bn','en'].includes(lang))lang='bn';if(!progress||typeof progress!=='object'||Array.isArray(progress))progress={};const last=read('emr30.last',''),now=today();selected=last&&validDate(last)?last:now<data.start?data.start:now>data.end?data.end:now;fromHash();render();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{})}).catch(()=>{$('#main').innerHTML=`<p class="empty-message">${t('loadError')}</p><button class="btn" onclick="location.reload()">Reload</button>`});
